function norm(s) {
  return String(s || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const user = norm(userRaw);

function numbered(intro, items) {
  const lines = items.map((it, i) => (i + 1) + '. ' + it.title);
  return intro.replace(/\s+$/, '') + '\n\n' + lines.join('\n');
}

function promptFor(sess) {
  return [
    'Mensaje del cliente:',
    prev.user_text || '',
    '',
    'Sesión:',
    JSON.stringify(sess),
    sess.motivo ? ('Motivo elegido en menú: ' + sess.motivo) : 'Sin motivo de menú.',
    sess.referencia ? ('Referencia elegida: ' + sess.referencia) : '',
    prev.outage ? ('DAÑO MASIVO activo: ' + prev.outage) : 'Sin flag de daño masivo en Redis.'
  ].filter(function (line) { return line !== ''; }).join('\n');
}

