const prev = $('Router Menú').first().json;
const session = Object.assign({}, prev.session || {});
const raw = $input.first().json || {};
const wrapped = raw && raw.body && typeof raw.body === 'object' && !Array.isArray(raw.body) && (raw.statusCode || raw.headers);
const body = wrapped ? raw.body : raw;
const statusCode = Number(raw.statusCode || body.statusCode || 0);

function normDoc(v) {
  return String(v || '').replace(/[\s.]/g, '').toUpperCase();
}

function rowsFrom(payload) {
  if (!payload || typeof payload !== 'object') return null;
  if (Array.isArray(payload)) return payload;
  if (Array.isArray(payload.data)) return payload.data;
  if (payload.data && typeof payload.data === 'object' && Array.isArray(payload.data.data)) return payload.data.data;
  return null;
}

const doc = normDoc(session.numero_documento);
const tipo = String(session.tipo_documento || '').trim();
const refBuscada = String(session.referencia_consulta || '').trim().toUpperCase();

function activo(nombre) {
  return String(nombre || '').toUpperCase().indexOf('ACTIVO') === 0;
}

function estadoNombre(r) {
  if (!r || r.estado_contrato == null || r.estado_contrato === '') return '';
  if (typeof r.estado_contrato === 'string') return r.estado_contrato;
  return r.estado_contrato.nombre || '';
}

const rawRows = rowsFrom(body);
const refs = [];
if (rawRows) {
  rawRows.forEach(function (r) {
    const sus = r && r.suscriptor ? r.suscriptor : {};
    const num = normDoc(sus.numero_documento);
    const cod = String(sus.tipo_documento && sus.tipo_documento.codigo != null ? sus.tipo_documento.codigo : '').trim();
    const est = estadoNombre(r);
    if (refBuscada) {
      if (String(r.referencia || '').trim().toUpperCase() !== refBuscada) return;
    } else {
      if (doc && num !== doc) return;
      if (tipo && cod && cod !== tipo) return;
    }
    if (est && !activo(est)) return;
    const inm = r.inmueble || {};
    refs.push({
      referencia: String(r.referencia || ''),
      direccion: String(inm.direccion || ''),
      municipio: String(inm.municipio || ''),
      nombre: String(sus.nombre_completo || '').trim(),
      cedula: num
    });
  });
}

function promptFor(sess) {
  return [
    'Mensaje del cliente:',
    prev.user_text || '',
    '',
    'Sesión:',
    JSON.stringify(sess),
    sess.motivo ? ('Motivo elegido en menú: ' + sess.motivo) : 'Sin motivo de menú.',
    sess.referencia ? ('Referencia elegida: ' + sess.referencia) : '',
    prev.outage ? ('DAÑO MASIVO activo: ' + prev.outage) : 'Sin flag de daño masivo en Redis.'
  ].filter(function (line) { return line !== ''; }).join('\n');
}

function emit(reply, items) {
  const marca = session.ultima_eleccion ? ('Elegiste: ' + session.ultima_eleccion + '\n\n') : '';
  session.ultima_eleccion = '';
  return [{
    json: Object.assign({}, prev, {
      session: session,
      active_agent: session.active_agent,
      route: 'menu',
      output: marca + reply,
      menu_items: items || [],
      text: promptFor(session)
    })
  }];
}

function detalleError() {
  let msg = '';
  if (body && typeof body === 'object') {
    if (typeof body.message === 'string') msg = body.message;
    else if (typeof body.error === 'string') msg = body.error;
    else if (body.error && typeof body.error.message === 'string') msg = body.error.message;
  }
  if (!msg && raw.error) {
    msg = typeof raw.error === 'string' ? raw.error : (raw.error.message || '');
  }
  return String(msg || '').replace(/\s+/g, ' ').trim().slice(0, 160);
}

function consultaFallida() {
  if (statusCode >= 400) return true;
  if (body && body.success === false) return true;
  if (raw.error) return true;
  if (rawRows === null) return true;
  return false;
}

const itemsNo = [
  { title: 'Intentar de nuevo', value: 'Intentar de nuevo' },
  { title: 'Ir a ventas', value: 'Ir a ventas' }
];
const datoAsk = 'Escribe tu cédula de ciudadanía, solo dígitos y sin puntos ni comas, o tu referencia (ejemplo BH00000).';

if (!doc && !refBuscada) {
  session.menu_state = 'doc_dato';
  session.numero_documento = '';
  session.referencia_consulta = '';
  session.tipo_documento = '';
  return emit('Necesito la cédula o la referencia para consultar.\n\n' + datoAsk, []);
}

if (consultaFallida()) {
  session.menu_state = 'doc_dato';
  session.numero_documento = '';
