  }
  const msgs = Array.isArray(conv.messages) ? conv.messages : [];
  for (let i = 0; i < msgs.length; i++) {
    const m = msgs[i];
    if (m && typeof m === 'object' && !esActividad(m)) lista.push(m);
  }
  let mejor = null;
  let mejorTs = -1;
  for (let i = 0; i < lista.length; i++) {
    const ts = epochDe(lista[i].created_at || lista[i].timestamp);
    if (ts >= mejorTs) {
      mejor = lista[i];
      mejorTs = ts;
    }
  }
  return { mensaje: mejor, ts: mejorTs < 0 ? 0 : mejorTs };
}

function esPending(conv) {
  const st = String(conv.status == null ? '' : conv.status).toLowerCase();
  return st === 'pending' || st === '2';
}

for (const item of $input.all()) {
  const raw = item.json || {};
  const statusCode = Number(raw.statusCode || 0);
  if (statusCode >= 400) continue;
  for (const conv of payloadDe(raw)) {
    if (!esPending(conv)) continue;
    const id = String(conv.id || '');
    if (!id || vistos[id]) continue;
    const ultimo = ultimoMensaje(conv);
    const contenido = String((ultimo.mensaje && (ultimo.mensaje.content || ultimo.mensaje.processed_message_content)) || '').trim();
    const esConfirmacion = contenido.indexOf(PREFIJO) === 0;
    const respaldo = epochDe(conv.timestamp) || epochDe(conv.last_activity_at);
    const tsMensaje = ultimo.ts || respaldo;
    let accion = '';
    if (esConfirmacion) {
      if (!tsMensaje || tsMensaje > limiteCierre) continue;
      accion = 'cerrar';
    } else {
      if (!tsMensaje || tsMensaje > limiteAviso) continue;
      accion = 'avisar';
    }
    vistos[id] = true;
    salida.push({
      json: {
        accion: accion,
        conversation_id: id,
        account_id: '1',
        chatwoot_base_url: 'https://chatwoot.buho-net.com'
      }
    });
  }
}
return salida;
